/* =============================================================
   data.js — Semua konten soal & permainan IPS
   Dipisah dari logika agar mudah dirawat / ditambah.

   STRUKTUR: soal dibagi 3 level (Beginner / Intermediate / Advanced).
   - 7 KUIS TOPIK  : 30 butir PER LEVEL (90 per topik).
   - 6 tantangan   : 10 butir per level (30 per game).
   Level bukan cuma mengubah panjang ronde, tapi juga TINGKAT
   KESULITAN soalnya. Soal diambil ACAK dari pool level yang dipilih,
   sehingga ronde jarang mengulang soal yang sama.

     QUIZ[topik].q[level] → [ [pertanyaan, [4 pilihan], indeks benar, penjelasan], ... ]  (30/level)
     TF[level]            → [ [pernyataan, benar?, penjelasan], ... ]                       (10/level)
     SORT[level]          → [ [barang, "K" (kebutuhan) | "I" (keinginan)], ... ]            (10/level)
     PROF[level]          → [ [petunjuk, [4 pilihan], indeks benar], ... ]                  (10/level)
     ORDER[level]         → [ [peristiwa, urutan], ... ]  (urutan 1..10 per level)
     MATCH1/2.pairs[level]→ [ [kiri, kanan], ... ]                                          (10/level)

   Jawaban benar sengaja ditaruh di indeks 0; pilihan diacak saat main.
   ============================================================= */

